mapper.update:
update artifact_sync_record
    set status=#{status}, update_time=#{updateTime}

            ,failed_reason=#{failedReason}

where sync_no = #{syncNo}

mapper.select:
select id, sync_no as syncNo from artifact_sync_record

    1 = 1
    and sync_progress is null

        and source_storage_id = #{storageId}


        and source_repository_id = #{repositoryId}

    and create_time < #{time}
